contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive c into a state where RState == BELOW_ONE and BASE_RESERVE < BASE_TARGET,
    // then call correctRState() and assert BASE_TARGET == BASE_RESERVE.
    // This holds in the original (P) because the original checks BASE_RESERVE_ < BASE_TARGET_
    // and updates targets; the mutant (M) flips the comparison and will not update.
    function runTest(
        address baseToken,
        address quoteToken,
        uint112 baseReserve,
        uint112 quoteReserve,
        uint112 baseTarget,
        uint112 quoteTarget,
        uint256 I,
        uint256 K
    ) public {
        // Preconditions for meaningful test: set storage via available external mutators.
        // We cannot write directly to storage, so require the contract already has appropriate public values.
        // We require the c currently reports RState BELOW_ONE, BASE_RESERVE < BASE_TARGET,
        // and that calling correctRState is allowed.

        // Check preconditions using public getters/view functions
        // getPMMStateForCall returns (i,K,B,Q,B0,Q0,R)
        (uint256 i,uint256 k,uint256 B,uint256 Q,uint256 B0,uint256 Q0,uint256 R) = c.getPMMStateForCall();

        require(R == uint256(PMMPricing.RState.BELOW_ONE), "PRE: R not BELOW_ONE");
        require(uint256(B) < uint256(B0), "PRE: BASE_RESERVE not less than BASE_TARGET");

        // Call the function that may change targets
        c.correctRState();

        // Read back PMM state after call
        (,,uint256 B_after,,uint256 B0_after,,) = c.getPMMStateForCall();

        // The invariant: after correctRState when previously BELOW_ONE and baseReserve < baseTarget,
        // baseTarget must be set equal to baseReserve. This holds in original P but is broken by mutant M.
        assert(B_after == B0_after);
    }

    // Fallback/receive to allow sending ETH if needed by external interactions
    receive() external payable {}
    fallback() external payable {}
}

